function isAlive(cell: Cell, liveCells: Cell[]): boolean {
  return liveCells.some((live) => isSameCell(cell, live));
}

function neighborsOf([x, y]: Cell): Cell[] {
  return [
    [x - 1, y - 1],
    [x, y - 1],
    [x + 1, y - 1],
    [x - 1, y],
    [x + 1, y],
    [x - 1, y + 1],
    [x, y + 1],
    [x + 1, y + 1],
  ];
}

export function nextGeneration(liveCells: Cell[]): Cell[] {
  const survivors = liveCells.filter((cell) =>
    survives(countLiveNeighbors(cell, liveCells)),
  );

  const born = liveCells
    .flatMap(neighborsOf)
    .filter((cell) => !isAlive(cell, liveCells))
    .filter((cell) => countLiveNeighbors(cell, liveCells) === 3)
    .filter(
      (cell, index, candidates) =>
        candidates.findIndex((other) => isSameCell(cell, other)) === index,
    );

  return [...survivors, ...born];
}

