toolUseResult.originalFile:
export type Cell = [number, number];

function isSameCell([x, y]: Cell, [otherX, otherY]: Cell): boolean {
  return x === otherX && y === otherY;
}

function isNeighbor(cell: Cell, other: Cell): boolean {
  const [x, y] = cell;
  const [otherX, otherY] = other;
  const isWithinOneStep = Math.abs(x - otherX) <= 1 && Math.abs(y - otherY) <= 1;
  return isWithinOneStep && !isSameCell(cell, other);
}

function countLiveNeighbors(cell: Cell, liveCells: Cell[]): number {
  return liveCells.filter((other) => isNeighbor(cell, other)).length;
}

function survives(liveNeighborCount: number): boolean {
  return liveNeighborCount === 2 || liveNeighborCount === 3;
}

export function nextGeneration(liveCells: Cell[]): Cell[] {
  return liveCells.filter((cell) => survives(countLiveNeighbors(cell, liveCells)));
}

